-- public.record_absence(p_team_id uuid, p_user_id uuid, p_from date, p_until date, p_from_time time without time zone, p_until_time time without time zone, p_idempotency_key uuid)
CREATE OR REPLACE FUNCTION public.record_absence(p_team_id uuid, p_user_id uuid, p_from date, p_until date, p_from_time time without time zone, p_until_time time without time zone, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid      uuid := (select auth.uid());
  who      uuid := coalesce(p_user_id, (select auth.uid()));
  org      uuid := private.team_organization(p_team_id);
  d_from   date := coalesce(p_from, (private.at_zurich(private.now()))::date);
  d_until  date := coalesce(p_until, p_from, (private.at_zurich(private.now()))::date);
  s_at     timestamptz;
  e_at     timestamptz;
  other    uuid;
  grp      uuid := gen_random_uuid();
  t        record;
  aid      uuid;
  n_teams  integer := 0;
  released integer := 0;
  past_planned integer := 0;
  n        integer;
begin
  if uid is null then return jsonb_build_object('result', 'rejected'); end if;
  s_at := private.at_zurich((d_from + coalesce(p_from_time, time '00:00')));
  e_at := case when p_until_time is null then private.at_zurich_end(((d_until + 1) + time '00:00'))
               else private.at_zurich_end((d_until + p_until_time)) end;
  if e_at <= s_at then
    raise exception 'the absence must end after it starts' using errcode = '22023';
  end if;
  if private.begin_command('record_absence', p_idempotency_key) then
    return jsonb_build_object('result', private.end_command('duplicate'));
  end if;
  if org is null or not private.is_org_member(org) or not private.is_team_member(p_team_id)
     or not exists (select 1 from public.team_memberships m where m.team_id = p_team_id and m.user_id = who) then
    return jsonb_build_object('result', private.end_command('rejected'));
  end if;
  -- Serialise absences of one person in the organisation: lock all her memberships there, in a fixed order.
  perform 1 from public.team_memberships m join public.teams tt on tt.id = m.team_id
    where m.user_id = who and tt.organization_id = org
    order by m.team_id
    for update of m;
  if e_at <= private.now() then
    return jsonb_build_object('result', private.end_command('in_past'));
  end if;
  select a.id into other from public.member_absences a
    where a.organization_id = org and a.user_id = who and a.withdrawn_at is null
      and a.starts_at < e_at and a.ends_at > s_at
    order by (a.team_id = p_team_id) desc, a.starts_at limit 1;
  if found then
    -- The id of a row of another team is not readable by the caller; return it only when it is her team's row.
    return jsonb_build_object('result', private.end_command('overlaps'),
      'absence_id', (select a.id from public.member_absences a where a.id = other and private.is_team_member(a.team_id)));
  end if;

  for t in
    select m.team_id from public.team_memberships m join public.teams tt on tt.id = m.team_id
    where m.user_id = who and tt.organization_id = org
    order by (m.team_id = p_team_id) desc, m.team_id
  loop
    insert into public.member_absences (id, organization_id, team_id, user_id, starts_at, ends_at, recorded_by, absence_group)
    values (case when t.team_id = p_team_id then grp else gen_random_uuid() end, org, t.team_id, who, s_at, e_at, uid, grp)
    returning id into aid;
    insert into public.absence_releases (absence_id, visit_id)
    select aid, r from private.release_visits_between(t.team_id, who, s_at, e_at, 'Abwesenheit', uid, false) r;
    get diagnostics n = row_count;
    -- ABS1-N1: count only the caller's own teams; another team's visits are not hers to know about.
    if private.is_team_member(t.team_id) then
      released := released + n;
      -- CSR1 / CGR-32: her planned visits dated before today inside the absence are not released (the release rule
      -- acts from today on); they keep her and are counted, so the caller learns they need a team decision.
      past_planned := past_planned + (
        select count(*)::int from public.care_visits x
        where x.team_id = t.team_id and x.responsible_user_id = who and x.status = 'planned'
          and x.visit_date < (private.at_zurich(private.now()))::date
          and private.visit_interval(x) && tstzrange(s_at, e_at, '[)'));
    end if;
    n_teams := n_teams + 1;
  end loop;

  return jsonb_build_object('result', private.end_command('ok'), 'absence_id', grp, 'released', released, 'teams', n_teams, 'past_planned', past_planned);
end;
$function$;

revoke all on function public.record_absence(p_team_id uuid, p_user_id uuid, p_from date, p_until date, p_from_time time without time zone, p_until_time time without time zone, p_idempotency_key uuid) from public, anon, authenticated, service_role;
grant execute on function public.record_absence(p_team_id uuid, p_user_id uuid, p_from date, p_until date, p_from_time time without time zone, p_until_time time without time zone, p_idempotency_key uuid) to authenticated;
grant execute on function public.record_absence(p_team_id uuid, p_user_id uuid, p_from date, p_until date, p_from_time time without time zone, p_until_time time without time zone, p_idempotency_key uuid) to service_role;
comment on function public.record_absence(p_team_id uuid, p_user_id uuid, p_from date, p_until date, p_from_time time without time zone, p_until_time time without time zone, p_idempotency_key uuid) is 'ABS1: records that a member (herself, or a colleague of one of her teams) is not available; no reason, no approval. Applies to every team of hers in the organisation (one row per team, one absence_group, ABS1-C3) and releases her planned visits from today on in each team at once (fixed text Abwesenheit). CGR-32: her planned visits dated before today inside the absence keep her and are counted in past_planned (caller''s teams only). Returns {result, absence_id, released, teams, past_planned}.';
